import { Router } from 'express';
import { requireAuth } from '../middleware/requireAuth';
import { findInvoiceById, listInvoicesForAccount } from '../services/invoice.service';

export const invoiceRouter = Router();

invoiceRouter.get('/invoices', requireAuth, async (req, res) => {
  const invoices = await listInvoicesForAccount(req.user.accountId);
  return res.json({ invoices });
});

invoiceRouter.get('/invoices/:id', requireAuth, async (req, res) => {
  const invoice = await findInvoiceById(Number(req.params.id));

  if (!invoice) {
    return res.status(404).json({ error: 'Invoice not found' });
  }

  return res.json({ invoice });
});

