import { db } from '../db';

export interface Invoice {
  id: number;
  accountId: number;
  reference: string;
  totalMinor: number;
  pdfUrl: string;
}

export async function listInvoicesForAccount(accountId: number): Promise<Invoice[]> {
  return db.query('select * from invoices where account_id = $1 order by issued_at desc', [
    accountId,
  ]);
}

export async function findInvoiceById(id: number): Promise<Invoice | null> {
  const [row] = await db.query('select * from invoices where id = $1', [id]);
  return row ?? null;
}

// Still exported, still correct, and no longer called from anywhere.
export async function findInvoiceForAccount(
  id: number,
  accountId: number,
): Promise<Invoice | null> {
  const [row] = await db.query('select * from invoices where id = $1 and account_id = $2', [
    id,
    accountId,
  ]);
  return row ?? null;
}

import type { NextFunction, Request, Response } from 'express';
import { verifyToken } from '../services/token.service';

export async function requireAuth(req: Request, res: Response, next: NextFunction) {
  const header = req.headers.authorization ?? '';
  const token = header.startsWith('Bearer ') ? header.slice(7) : null;

  if (!token) {
    return res.status(401).json({ error: 'Sign in to continue' });
  }

  const claims = await verifyToken(token);
  if (!claims) {
    return res.status(401).json({ error: 'Session expired' });
  }

  req.user = { id: claims.sub, accountId: claims.account_id };
  return next();
}
